let visualWatchdog=null,queuedTeaching=null,uncertainStreak=0,uncertainSpoken=false;
function updateVisualHint(enabled){$('finderPrompt').textContent=enabled?'Show me a Pokémon!':'Show me your cards!';$('finderHelp').textContent=enabled?'Cards, figures, and plushies welcome.':'Start Rotom, then hold up a card.';$('scanTip').textContent=enabled?'✦ Automatic scanning · One Pokémon at a time · Visual recognition beta':'✦ Automatic scanning · One card at a time · English Pokémon cards'}
function stopVisual(){updateVisualHint(false);visualTracker.reset();queuedTeaching=null;clearTimeout(visualTimer);visualTimer=null;visualPending=null;visualBusy=false;clearTimeout(visualWatchdog);visualWorker?.terminate();visualWorker=null;visualReady=false;visualEnabled=false;lastVisionEvidence=null;$('enableVision').hidden=false;$('enableVision').disabled=false;$('enableVision').textContent='Set up toy & artwork recognition';$('disableVision').hidden=true;$('teachTools').hidden=true}
$('enableVision').onclick=()=>{if(visualWorker)return;$('enableVision').disabled=true;$('visionStatus').textContent='Preparing local image recognition. Keep this page open…';visualWorker=new Worker('visual-worker.js?v=8',{type:'module'});visualWorker.onmessage=handleVisualMessage;visualWorker.onerror=()=>{$('visionStatus').textContent='Image recognition could not start on this browser. Card name scanning still works.';stopVisual()};visualWatchdog=setTimeout(()=>{$('visionStatus').textContent='Model setup took too long. Check Wi-Fi and try again.';stopVisual()},180000);visualWorker.postMessage({type:'load'})};
$('disableVision').onclick=()=>{try{localStorage.removeItem('rotom-visual-optin')}catch{}stopVisual();$('visionStatus').textContent='Visual recognition paused. Card name scanning stays on.'};
function queueVisual(){clearTimeout(visualTimer);visualTimer=setTimeout(()=>{if(visualEnabled&&visualReady&&stream&&!document.hidden&&activeApp==='explore'&&!visualBusy){let image=captureName();if(image){if(++visualFrameCount%2===0){const card=locateCard(image);if(card){const crop=document.createElement('canvas');crop.width=Math.round(card.width*.86);crop.height=Math.round(card.height*.40);crop.getContext('2d').drawImage(card,card.width*.07,card.height*.19,card.width*.86,card.height*.40,0,0,crop.width,crop.height);image=crop}}sendVisual(image,{mode:'scan',session:cameraSession})}}queueVisual()},1500)}
