async function handleVisualMessage({data:m}){if(m.type==='progress'){$('visionStatus').textContent=m.text;return}if(m.type==='ready'){clearTimeout(visualWatchdog);visualReady=true;visualEnabled=true;updateVisualHint(true);try{localStorage.setItem('rotom-visual-optin','1')}catch{}$('enableVision').hidden=true;$('disableVision').hidden=false;$('teachTools').hidden=false;$('visionStatus').textContent='Local image recognition ready. No per-scan charges. Start the camera to try a toy.';queueVisual();return}
 if(m.type==='error'){clearTimeout(visualWatchdog);visualBusy=false;visualPending=null;$('visionStatus').textContent='Image model error: '+m.message+'. Card name scanning still works.';stopVisual();return}
 if(m.type!=='result')return;clearTimeout(visualWatchdog);const pending=visualPending;visualPending=null;visualBusy=false;if(queuedTeaching){const queued=queuedTeaching;queuedTeaching=null;if(queued.context.session===cameraSession&&stream&&!document.hidden){sendVisual(queued.image,queued.context);$('visionStatus').textContent='Remembering this angle…';return}}if(!pending||pending.request!==m.request||pending.session!==cameraSession||document.hidden)return;
 if(pending.mode==='teach'){if(toyViews.length>=100){$('visionStatus').textContent='100 views are saved. Export a backup before forgetting old views.';return}const view={id:pending.id,vector:m.vector};try{const views=[...toyViews,view];localStorage.setItem('rotom-toys-v1',JSON.stringify(views));toyViews=views;reloadToys();$('visionStatus').textContent='Remembered! Turn the toy to another angle for the next view.'}catch{$('visionStatus').textContent='Could not save this view. Browser storage may be full.'}return}
 if(!stream||!visualEnabled||activeApp!=='explore')return;const decision=visualDecision(m.ranks,m.artRanks,m.vector,toyViews);const seconds=((performance.now()-visualStarted)/1000).toFixed(1);$('visionStatus').textContent=decision?'Image check: '+decision.source+' · '+seconds+' s':'No confident visual match · '+seconds+' s. Teach a few angles if this is a familiar toy.';
 if(!decision){visualTracker.clearEvidence();if(m.ranks[0]?.id&&m.ranks[0].score>=.30){uncertainStreak++;if(uncertainStreak>=3&&!uncertainSpoken&&rotomVoice.audio.paused&&(!lastVisualConfirmed||performance.now()-lastVisualConfirmed.at>8000)){uncertainSpoken=true;rotomVoice.phrase('uncertain')}}else uncertainStreak=0;return}uncertainStreak=0;if(performance.now()-visualStarted>8000){$('visionStatus').textContent='This image check was slow. Try taught toy views or card names for faster results.';return}const p=allPokemon.find(p=>p.id===decision.id);if(!p)return;if(decision.score>=1)lastVisionEvidence={name:p.name,at:performance.now(),session:cameraSession,frameId:'visual-'+m.request,used:false};rotomVoice.preloadEntry(p.id);if(p.name===tracker.lastRecognized){lastVisualConfirmed={name:p.name,at:performance.now(),session:cameraSession};return}
 if(lastOcrEvidence&&performance.now()-lastOcrEvidence.at<4000&&lastOcrEvidence.name!==p.name){visualTracker.clearEvidence();return}visualTracker.lastRecognized=tracker.lastRecognized;const matchingName=decision.score>=1&&lastOcrEvidence?.name===p.name&&performance.now()-lastOcrEvidence.at<4000;const recognized=matchingName?tracker.observe([{id:p.id,name:p.name,score:decision.score}],performance.now(),'visual-'+m.request):visualTracker.observe([{id:p.id,name:p.name,score:decision.score}],performance.now(),'visual-'+m.request);if(matchingName&&lastVisionEvidence)lastVisionEvidence.used=true;if(!recognized)return;tracker.lastRecognized=p.name;tracker.clearEvidence();uncertainSpoken=false;lastVisualConfirmed={name:p.name,at:performance.now(),session:cameraSession};
 status('Recognized '+p.display+'!');setAutoLabel('✓ '+p.display);const session=cameraSession;const loaded=await loadPokemon(p.name,true,()=>session===cameraSession&&!document.hidden&&visualEnabled&&activeApp==='explore',true);if(!loaded)tracker.retry(p.name);
}
$('teachToy').onclick=()=>{if(!visualReady)return;if(!stream){$('visionStatus').textContent='Start the camera first, then point it at one toy.';return}const image=captureName();if(image){const context={mode:'teach',session:cameraSession,id:Number($('teachSpecies').value)};if(visualBusy){queuedTeaching={image,context};$('visionStatus').textContent='This view is queued. Finishing the previous image…';return}sendVisual(image,context);$('visionStatus').textContent='Remembering this angle…'}};
$('forgetToys').onclick=()=>{try{if(!confirm('Forget all taught toy views? Export a Trainer ID backup first if you want to keep them.'))return;localStorage.removeItem('rotom-toys-v1');reloadToys();$('visionStatus').textContent='Taught toy views forgotten.'}catch{$('visionStatus').textContent='Could not clear saved views.'}};
